<?php $pageTitle='Add client'; $activePage='clients'; require_once __DIR__.'/../includes/header.php'; require_permission('manage_clients'); if($_SERVER['REQUEST_METHOD']==='POST'){if(!verify_csrf($_POST['csrf']??null)){flash('danger','Security token expired.');}else{$statement=$pdo->prepare('INSERT INTO clients(name,company,email,phone,website,address,notes) VALUES (?,?,?,?,?,?,?)');$statement->execute([trim($_POST['name']),trim($_POST['company']),trim($_POST['email']),trim($_POST['phone']),trim($_POST['website']),trim($_POST['address']),trim($_POST['notes'])]);record_activity('Created client','client',(int)$pdo->lastInsertId());flash('success','Client created.');redirect('clients/');}} ?><div class="mb-4"><span class="section-kicker">New relationship</span><h2 class="mt-2">Add a client</h2></div><form method="post" class="panel form-panel"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><div class="row g-3"><div class="col-md-6"><label class="form-label">Contact name<input name="name" class="form-control" required></label></div><div class="col-md-6"><label class="form-label">Company<input name="company" class="form-control" required></label></div><div class="col-md-6"><label class="form-label">Email<input name="email" type="email" class="form-control" required></label></div><div class="col-md-6"><label class="form-label">Phone<input name="phone" class="form-control"></label></div><div class="col-md-6"><label class="form-label">Website<input name="website" type="url" class="form-control" placeholder="https://"></label></div><div class="col-12"><label class="form-label">Address<textarea name="address" class="form-control" rows="2"></textarea></label></div><div class="col-12"><label class="form-label">Notes<textarea name="notes" class="form-control" rows="4"></textarea></label></div></div><div class="mt-4 d-flex gap-2"><button class="btn btn-primary">Save client</button><a href="<?= url('clients/') ?>" class="btn btn-light">Cancel</a></div></form><?php require_once __DIR__.'/../includes/footer.php'; ?>
